    def in_bounds(x, y):
        return (w <= 0 or 0 <= x < w) and (h <= 0 or 0 <= y < h)

    def manhattan(ax, ay, bx, by):
        return abs(ax - bx) + abs(ay - by)

    # Infer immediate mode from available info
    opp_dist = manhattan(sx, sy, ox, oy)
