        elif observation.get("opponent_position") is not None:
            d = manhattan(nx, ny, ox, oy)
            if chase_mode:
                score -= d * 6
            else:
                score += d * 6

        # Avoid revisiting own path unless necessary
        if (nx, ny) in path_set:
            score -= 4

        # Prefer not to get stuck on borders when options exist
